out.push("\n\n你可以先不填写任何内容，直接点击提交，再逐渐修正错误，观察 `aria-invalid` 和错误关联关系的变化。\n\n### 12.2 HTML 实现\n\n```html\n<form id=\"register-form\">\n  <div\n    id=\"error-summary\"\n    tabindex=\"-1\"\n    hidden\n  >\n    <h2 id=\"error-summary-title\"></h2>\n    <ul id=\"error-list\"></ul>\n  </div>\n\n  <div class=\"form-field\">\n    <label for=\"email\">\n      Email address (required)\n    </label>\n\n    <input\n      id=\"email\"\n      name=\"email\"\n      type=\"email\"\n      autocomplete=\"email\"\n      required\n    >\n\n    <p\n      id=\"email-error\"\n      class=\"field-error\"\n      hidden\n    ></p>\n  </div>\n\n  <div class=\"form-field\">\n    <label for=\"password\">\n      Password (required)\n    </label>\n\n    <input\n      id=\"password\"\n      name=\"password\"\n      type=\"password\"\n      autocomplete=\"new-password\"\n      minlength=\"8\"\n      required\n      aria-describedby=\"password-help\"\n    >\n\n    <p id=\"password-help\">\n      Use at least 8 characters.\n    </p>\n\n    <p\n      id=\"password-error\"\n      class=\"field-error\"\n      hidden\n    ></p>\n  </div>\n\n  <button type=\"submit\">\n    Create account\n  </button>\n\n  <div id=\"form-status\" role=\"status\"></div>\n</form>\n```\n\n这里没有在 HTML 中直接设置 `novalidate`，是为了保留 JavaScript 加载失败时的原生验证能力。\n\n### 12.3 CSS 实现\n\n```css\n.form-field {\n  margin-bottom: 20px;\n}\n\n.form-field label {\n  display: block;\n  margin-bottom: 8px;\n}\n\n.form-field input {\n  box-sizing: border-box;\n  width: 100%;\n  min-height: 44px;\n  padding: 12px;\n  border: 1px solid #767676;\n  border-radius: 4px;\n  font: inherit;\n}\n\n.form-field input[aria-invalid=\"true\"] {\n  border: 2px solid #b00020;\n}\n\n.field-error {\n  color: #b00020;\n  margin-top: 8px;\n}\n\n:focus-visible {\n  outline: 2px solid #005fcc;\n  outline-offset: 3px;\n}\n\n#error-summary {\n  border: 2px solid #b00020;\n  padding: 16px;\n  margin-bottom: 24px;\n}\n\n[hidden] {\n  display: none !important;\n}\n```\n\n这里直接使用 `aria-invalid` 作为 CSS 状态选择器。\n\n这样做有一个好处：视觉错误状态与无障碍错误状态来自同一个属性，不容易出现红色边框已经消失，但 ARIA 仍然显示错误的情况。\n\n### 12.4 JavaScript 实现\n\n```javascript\nconst form = document.querySelector('#register-form');\nconst email = document.querySelector('#email');\nconst password = document.querySelector('#password');\n\nconst summary = document.querySelector('#error-summary');\nconst summaryTitle = document.querySelector(\n  '#error-summary-title'\n);\nconst errorList = document.querySelector('#error-list');\nconst status = document.querySelector('#form-status');\n\nconst fields = [email, password];\n\nlet submitted = false;\n```\n\n第一步：编写验证函数。\n\n```javascript\nfunction getError(input) {\n  const validity = input.validity;\n\n  if (validity.valueMissing) {\n    return input === email\n      ? 'Enter your email address.'\n      : 'Enter your password.';\n  }\n\n  if (validity.typeMismatch) {\n    return 'Enter a valid email address.';\n  }\n\n  if (\n    input === password &&\n    input.value.length < 8\n  ) {\n    return 'Use at least 8 characters.';\n  }\n\n  return validity.valid\n    ? ''\n    : input.validationMessage;\n}\n```\n\n第二步：编写通用错误状态更新函数。\n\n```javascript\nfunction updateFieldError(input, message) {\n  const error = document.getElementById(\n    `${input.id}-error`\n  );\n\n  const descriptions = new Set(\n    (input.getAttribute('aria-describedby') || '')\n      .split(/\\s+/)\n      .filter(Boolean)\n  );\n\n  if (message) {\n    input.setAttribute('aria-invalid', 'true');\n\n    error.textContent = message;\n    error.hidden = false;\n\n    descriptions.add(error.id);\n  } else {\n    input.removeAttribute('aria-invalid');\n\n    error.textContent = '';\n    error.hidden = true;\n\n    descriptions.delete(error.id);\n  }\n\n  if (descriptions.size) {\n    input.setAttribute(\n      'aria-describedby',\n      [...descriptions].join(' ')\n    );\n  } else {\n    input.removeAttribute('aria-describedby');\n  }\n}\n```\n\n这里使用 Set 来管理 `aria-describedby`。\n\n因为密码输入框原本就有：\n\n```html\naria-describedby=\"password-help\"\n```\n\n验证失败后应该变为：\n\n```html\naria-describedby=\"password-help password-error\"\n```\n\n修正错误后再恢复为：\n\n```html\naria-describedby=\"password-help\"\n```\n\n如果直接覆盖整个属性，就可能导致原有的说明信息丢失。\n\n第三步：实现错误摘要。\n\n```javascript\nfunction renderSummary(errors) {\n  errorList.replaceChildren();\n\n  if (!errors.length) {\n    summary.hidden = true;\n    return;\n  }\n\n  summaryTitle.textContent =\n    errors.length === 1\n      ? 'There is 1 error'\n      : `There are ${errors.length} errors`;\n\n  errors.forEach(({ input, message }) => {\n    const li = document.createElement('li');\n    const link = document.createElement('a');\n\n    link.href = `#${input.id}`;\n    link.textContent = message;\n\n    link.addEventListener('click', event => {\n      event.preventDefault();\n      input.focus();\n    });\n\n    li.appendChild(link);\n    errorList.appendChild(li);\n  });\n\n  summary.hidden = false;\n}\n```\n\n第四步：实现完整验证流程。\n\n```javascript\nfunction validateForm() {\n  const errors = [];\n\n  fields.forEach(input => {\n    const message = getError(input);\n\n    updateFieldError(input, message);\n\n    if (message) {\n      errors.push({ input, message });\n    }\n  });\n\n  renderSummary(errors);\n\n  return errors;\n}\n```\n\n第五步：处理提交及输入事件。\n\n```javascript\nform.addEventListener('submit', event => {\n  event.preventDefault();\n\n  submitted = true;\n  status.textContent = '';\n\n  const errors = validateForm();\n\n  if (errors.length) {\n    summary.focus();\n    return;\n  }\n\n  // 此处应调用真实业务 API。\n  // 示例仅展示前端验证，不代表账户已创建。\n  status.textContent =\n    'Form validated successfully.';\n});\n\nfields.forEach(input => {\n  input.addEventListener('input', () => {\n    status.textContent = '';\n\n    if (!submitted) return;\n\n    validateForm();\n  });\n});\n\n// 自定义验证初始化完成后，关闭浏览器原生提示。\nform.noValidate = true;\n```\n\n这套实现解决了以下问题：\n\n");
